\chapter*{CHAPTER XXI: CURVES FOR REFERENCE}

For the convenience of the student a number of the more common curves employed in the text are collected here.

\textsc{Cubical Parabola}


\[ y = ax^3. \]

\textsc{Semicubical Parabola}


\[ y^2 = ax^3. \]

\textsc{The Witch of Agnesi}


\[ x^2 y = 4\,a^2\,(2\,a - y). \]

\textsc{The Cissoid of Diocles}


\[ y^2\,(2\,a - x) = x^3. \]


\textsc{The Lemniscate of Bernoulli}
\[(x^2+y^2)^2=a^2(x^2-y^2).\]
\[\rho^2=a^2\cos 2\,\theta.\]

\textsc{The Conchoid of Nicomedes}
\[x^2y^2=(y+a)^2(b^2-y^2).\]
\[\rho=a\csc\theta+b.\]

\textsc{Cycloid, Ordinary Case}
\[x=a\operatorname{arc\,vers}\frac{y}{a}-\sqrt{2\,ay-y^2}.\]
\[\left\{\begin{array}{l} x=a(\theta-\sin\theta),\\ y=a(1-\cos\theta). \end{array}\right.\]

\textsc{Cycloid, Vertex at Origin}
\[x=a\operatorname{arc\,vers}\frac{y}{a}+\sqrt{2\,ay-y^2}.\]
\[\left\{\begin{array}{l} x=a(\theta+\sin\theta),\\ y=a(1-\cos\theta). \end{array}\right.\]

\textsc{Catenary}
\[y=\frac{a}{2}\left(e^{\frac{x}{a}}+e^{-\frac{x}{a}}\right).\]

\textsc{Parabola}
\[x^{\frac{1}{2}}+y^{\frac{1}{2}}=a^{\frac{1}{2}}.\]


\textsc{Hypocycloid of Four Cusps}


\[ x^{\frac{2}{3}} + y^{\frac{2}{3}} = a^{\frac{2}{3}}. \]
\[ \left\{\begin{array}{l} x = a\cos^{3}\theta, \\ y = a\sin^{3}\theta. \end{array}\right. \]

\textsc{Evolute of Ellipse}


\[ (ax)^{\frac{2}{3}} + (by)^{\frac{2}{3}} = (a^{2} - b^{2})^{\frac{2}{3}} \]

\textsc{Cardioid}


\[ x^{2} + y^{2} + ax = a\sqrt{x^{2} + y^{2}}. \]
\[ \rho = a\,(1 - \cos\theta). \]

\textsc{Folium of Descartes}


\[ x^{3} + y^{3} - 3\,axy = 0. \]

\textsc{Sine Curve}


\[ y = \sin x. \]

\textsc{Cosine Curve}


\[ y = \cos x. \]


\textsc{Limaçon}


\[ \rho = b - a\cos\theta. \]

\textsc{Strophoid}


\[ y^2 = x^2\,\frac{a+x}{a-x}. \]

\textsc{Spiral of Archimedes}


\[ \rho = a\theta. \]

\textsc{Logarithmic or Equiangular Spiral}


\[ \rho = e^{a\theta}, \text{ or} \]
\[ \log\rho = a\theta. \]

\textsc{Hyperbolic or Reciprocal Spiral}


\[ \rho\theta = a. \]

\textsc{Lituus}


\[ \rho^2\theta = a^2. \]


\textsc{Parabolic Spiral}


\[ (\rho - a)^2 = 4\,ac\theta. \]

\textsc{Logarithmic Curve}


\[ y = \log x. \]

\textsc{Exponential Curve}


\[ y = e^{x}. \]

\textsc{Probability Curve}


\[ y = e^{-x^{2}}. \]

\textsc{Secant Curve}


\[ y = \sec x. \]

\textsc{Tangent Curve}


\[ y = \tan x. \]

\textsc{Three-Leaved Rose}
\[ \rho = a \sin 3\,\theta. \]
\textsc{Three-Leaved Rose}
\[ \rho = a \cos 3\,\theta. \]
\textsc{Four-Leaved Rose}
\[ \rho = a \sin 2\,\theta. \]
\textsc{Four-Leaved Rose}
\[ \rho = a \cos 2\,\theta. \]
\textsc{Two-Leaved Rose Lemniscate}
\[ \rho^{2} = a^{2} \sin 2\,\theta. \]
\textsc{Eight-Leaved Rose}
\[ \rho = a \sin 4\,\theta. \]


\textsc{Curve with End Point at Origin}


\[ y = x \log x. \]

\textsc{Curve with Salient Point at Origin}


\[ y\left(1+e^{\frac{1}{x}}\right) = x. \]

\textsc{Curve with Conjugate (Isolated) Point at the Origin}


\[ y^{2} = x^{3} - x^{2}. \]

\textsc{Curve with Cusp of Second Kind at Origin}


\[ (y - x^{2})^{2} = x^{5}. \]

\textsc{Parabola}


\[ \rho = a \sec^{2} \frac{\theta}{2}. \]

\textsc{Equilateral Hyperbola}


\[ xy = a. \]

